-- Mining Match - database schema (SQLite for dev/tests; written to port to PostgreSQL).
--
-- Conventions
--   * ids are TEXT (uuid4 hex generated by the app) so they work unchanged on SQLite and Postgres
--   * dates are ISO 'YYYY-MM-DD' (use DATE in Postgres); timestamps are UTC
--   * booleans are INTEGER 0/1 with a CHECK (use BOOLEAN in Postgres)
--   * column names follow the matching engine's input shapes, so rows feed it directly
--   * run with foreign keys ON (SQLite: PRAGMA foreign_keys = ON on every connection)
--   * uploaded files are NOT stored here, only their storage_key (disk/S3 path)

CREATE TABLE IF NOT EXISTS users (
  id            TEXT PRIMARY KEY,
  email         TEXT NOT NULL UNIQUE,              -- stored lower-case
  password_hash TEXT,                              -- supplied by the auth layer; never plain text
  role          TEXT NOT NULL CHECK (role IN ('candidate', 'employer', 'admin')),
  is_active     INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),   -- 0 = account suspended
  email_verified_at TEXT,                         -- NULL until the emailed link is used
  created_at    TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- Shared vocabulary of licences, qualifications and skills. One row per concept, so
-- "SS11" and "Standard 11" end up as the same item (see catalog_aliases).
CREATE TABLE IF NOT EXISTS catalog_items (
  id              TEXT PRIMARY KEY,
  kind            TEXT NOT NULL CHECK (kind IN ('licence', 'qualification', 'skill')),
  name            TEXT NOT NULL,                   -- display name (first spelling seen)
  normalized_name TEXT NOT NULL,                   -- engine-normalised key
  renew_years     INTEGER CHECK (renew_years IS NULL OR renew_years BETWEEN 1 AND 20),  -- usual renewal cycle
  renew_note      TEXT,                            -- shown when someone adds it, e.g. site variations
  UNIQUE (kind, normalized_name),
  UNIQUE (id, kind)                                -- lets link tables enforce the kind via composite FK
);

CREATE TABLE IF NOT EXISTS catalog_aliases (
  alias     TEXT PRIMARY KEY,                      -- lower-case, e.g. 'ss11'
  canonical TEXT NOT NULL                          -- lower-case, e.g. 'standard 11'
);

-- ------------------------------------------------------------------ candidates
CREATE TABLE IF NOT EXISTS candidates (
  id                  TEXT PRIMARY KEY,
  user_id             TEXT NOT NULL UNIQUE REFERENCES users (id) ON DELETE CASCADE,
  name                TEXT NOT NULL,
  phone               TEXT,
  location            TEXT,                        -- compared with job.location; keep values consistent (e.g. state code)
  willing_to_relocate INTEGER NOT NULL DEFAULT 0 CHECK (willing_to_relocate IN (0, 1)),
  willing_fifo        INTEGER NOT NULL DEFAULT 0 CHECK (willing_fifo IN (0, 1)),
  available_from      TEXT,
  summary             TEXT,
  is_active           INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),
  expiry_reminders    INTEGER NOT NULL DEFAULT 1 CHECK (expiry_reminders IN (0, 1)),  -- email before licences expire
  reminder_token      TEXT,                        -- random; only lets its holder turn reminders off
  created_at          TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at          TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS documents (
  id          TEXT PRIMARY KEY,
  candidate_id TEXT NOT NULL REFERENCES candidates (id) ON DELETE CASCADE,
  kind        TEXT NOT NULL CHECK (kind IN ('licence', 'qualification', 'resume', 'other')),
  filename    TEXT NOT NULL,
  mime_type   TEXT,
  size_bytes  INTEGER CHECK (size_bytes IS NULL OR size_bytes >= 0),
  storage_key TEXT NOT NULL UNIQUE,
  verified_at TEXT,                                -- set when a recruiter/admin has checked the document
  uploaded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS candidate_licences (
  candidate_id TEXT NOT NULL REFERENCES candidates (id) ON DELETE CASCADE,
  item_id      TEXT NOT NULL,
  kind         TEXT NOT NULL DEFAULT 'licence' CHECK (kind = 'licence'),
  expiry_date  TEXT,                               -- NULL = no expiry
  document_id  TEXT REFERENCES documents (id) ON DELETE SET NULL,
  PRIMARY KEY (candidate_id, item_id),             -- a renewal updates expiry_date in place
  FOREIGN KEY (item_id, kind) REFERENCES catalog_items (id, kind)
);

CREATE TABLE IF NOT EXISTS candidate_qualifications (
  candidate_id TEXT NOT NULL REFERENCES candidates (id) ON DELETE CASCADE,
  item_id      TEXT NOT NULL,
  kind         TEXT NOT NULL DEFAULT 'qualification' CHECK (kind = 'qualification'),
  awarded_date TEXT,
  institution  TEXT,
  document_id  TEXT REFERENCES documents (id) ON DELETE SET NULL,
  PRIMARY KEY (candidate_id, item_id),
  FOREIGN KEY (item_id, kind) REFERENCES catalog_items (id, kind)
);

CREATE TABLE IF NOT EXISTS candidate_skills (
  candidate_id TEXT NOT NULL REFERENCES candidates (id) ON DELETE CASCADE,
  item_id      TEXT NOT NULL,
  kind         TEXT NOT NULL DEFAULT 'skill' CHECK (kind = 'skill'),
  years        REAL CHECK (years IS NULL OR years >= 0),   -- NULL = years not stated
  PRIMARY KEY (candidate_id, item_id),
  FOREIGN KEY (item_id, kind) REFERENCES catalog_items (id, kind)
);

-- Years of experience are derived from the dates (open-ended role = still working there).
CREATE TABLE IF NOT EXISTS candidate_experience (
  id            TEXT PRIMARY KEY,
  candidate_id  TEXT NOT NULL REFERENCES candidates (id) ON DELETE CASCADE,
  role          TEXT NOT NULL,
  employer_name TEXT,
  start_date    TEXT NOT NULL,
  end_date      TEXT,
  CHECK (end_date IS NULL OR end_date >= start_date)
);

-- ------------------------------------------------------------------- employers
CREATE TABLE IF NOT EXISTS employers (
  id           TEXT PRIMARY KEY,
  user_id      TEXT NOT NULL UNIQUE REFERENCES users (id) ON DELETE CASCADE,
  company_name TEXT NOT NULL,
  contact_name TEXT,
  phone        TEXT,
  location     TEXT,
  abn             TEXT,                          -- 11 digits, checked with the ABN check digits
  billing_email   TEXT,                          -- where invoices go (account email if empty)
  billing_address TEXT,
  created_at   TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS jobs (
  id                   TEXT PRIMARY KEY,
  employer_id          TEXT NOT NULL REFERENCES employers (id) ON DELETE CASCADE,
  title                TEXT NOT NULL,
  description          TEXT,
  location             TEXT,
  start_date           TEXT,
  min_experience_years REAL CHECK (min_experience_years IS NULL OR min_experience_years >= 0),
  status               TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'open', 'filled', 'closed')),
  created_at           TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at           TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- One table for every licence / qualification / skill a job asks for.
CREATE TABLE IF NOT EXISTS job_requirements (
  job_id    TEXT NOT NULL REFERENCES jobs (id) ON DELETE CASCADE,
  item_id   TEXT NOT NULL,
  kind      TEXT NOT NULL CHECK (kind IN ('licence', 'qualification', 'skill')),
  required  INTEGER NOT NULL DEFAULT 1 CHECK (required IN (0, 1)),   -- 0 = preferred
  min_years REAL CHECK (min_years IS NULL OR min_years >= 0),
  CHECK (min_years IS NULL OR kind = 'skill'),
  PRIMARY KEY (job_id, item_id),
  FOREIGN KEY (item_id, kind) REFERENCES catalog_items (id, kind)
);

CREATE TABLE IF NOT EXISTS job_relevant_roles (
  job_id TEXT NOT NULL REFERENCES jobs (id) ON DELETE CASCADE,
  role   TEXT NOT NULL,
  PRIMARY KEY (job_id, role)
);

-- ------------------------------------------------------------------ shortlists
CREATE TABLE IF NOT EXISTS shortlists (
  id          TEXT PRIMARY KEY,
  employer_id TEXT NOT NULL REFERENCES employers (id) ON DELETE CASCADE,
  job_id      TEXT REFERENCES jobs (id) ON DELETE SET NULL,
  name        TEXT NOT NULL,
  created_at  TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS shortlist_entries (
  shortlist_id TEXT NOT NULL REFERENCES shortlists (id) ON DELETE CASCADE,
  candidate_id TEXT NOT NULL REFERENCES candidates (id) ON DELETE CASCADE,
  status       TEXT NOT NULL DEFAULT 'shortlisted'
               CHECK (status IN ('shortlisted', 'contacted', 'interviewing', 'offered', 'placed', 'rejected')),
  notes        TEXT,
  score_at_add REAL,                               -- engine score when first added (snapshot)
  added_at     TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at   TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (shortlist_id, candidate_id)
);

-- ----------------------------------------------------------- access control
-- Contact details stay hidden from an employer until the candidate agrees. An employer asks
-- ('requested'); the candidate grants or declines. A candidate can also grant without being asked,
-- and can take it back later (status goes to 'declined', which also stops repeat requests).
CREATE TABLE IF NOT EXISTS contact_releases (
  candidate_id TEXT NOT NULL REFERENCES candidates (id) ON DELETE CASCADE,
  employer_id  TEXT NOT NULL REFERENCES employers (id) ON DELETE CASCADE,
  job_id       TEXT REFERENCES jobs (id) ON DELETE SET NULL,     -- job the request was about
  status       TEXT NOT NULL DEFAULT 'requested' CHECK (status IN ('requested', 'granted', 'declined')),
  requested_at TEXT,
  decided_at   TEXT,
  PRIMARY KEY (candidate_id, employer_id)
);

-- Who did what to which record. Deliberately no foreign keys: entries must outlive the
-- accounts and records they mention. Holds ids and short reasons only, never personal details.
-- (id is an auto-increment integer: BIGSERIAL / GENERATED ALWAYS AS IDENTITY in PostgreSQL.)
CREATE TABLE IF NOT EXISTS audit_log (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  at            TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  user_id       TEXT,
  role          TEXT,
  action        TEXT NOT NULL,
  outcome       TEXT NOT NULL CHECK (outcome IN ('allowed', 'denied')),
  resource_type TEXT,
  resource_id   TEXT,
  detail        TEXT
);

-- ------------------------------------------------------------ login and sessions
-- Times in these auth tables are unix seconds (INTEGER), which makes expiry checks simple.
-- Tokens are random and only their SHA-256 hash is stored, so a copy of the database can't be
-- used to log in.
CREATE TABLE IF NOT EXISTS sessions (
  token_hash   TEXT PRIMARY KEY,
  user_id      TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  created_at   INTEGER NOT NULL,
  expires_at   INTEGER NOT NULL,
  last_seen_at INTEGER NOT NULL
);

-- One-time links sent by email.
CREATE TABLE IF NOT EXISTS auth_tokens (
  token_hash TEXT PRIMARY KEY,
  user_id    TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  purpose    TEXT NOT NULL CHECK (purpose IN ('verify_email', 'reset_password')),
  expires_at INTEGER NOT NULL,
  used_at    INTEGER
);

-- ------------------------------------------------------- two-factor login (admins)
-- One row per account with two-factor on: the authenticator app's shared secret and the last
-- 30-second step used, so a code can't be used twice.
CREATE TABLE IF NOT EXISTS two_factor (
  user_id    TEXT PRIMARY KEY REFERENCES users (id) ON DELETE CASCADE,
  secret     TEXT NOT NULL,                      -- base32 TOTP secret
  enabled_at TEXT,
  last_step  INTEGER
);

-- One-time recovery codes, hashed.
CREATE TABLE IF NOT EXISTS recovery_codes (
  code_hash TEXT PRIMARY KEY,
  user_id   TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  used_at   TEXT
);

-- The second step of a login: issued after a correct password, used once. 'required' = enter a
-- code; 'setup' = first login, set up the app (pending_secret holds the secret being set up).
CREATE TABLE IF NOT EXISTS login_challenges (
  token_hash     TEXT PRIMARY KEY,
  user_id        TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  purpose        TEXT NOT NULL CHECK (purpose IN ('required', 'setup')),
  expires_at     INTEGER NOT NULL,                -- unix seconds
  tries          INTEGER NOT NULL DEFAULT 0,
  pending_secret TEXT
);

-- Counts recent attempts (failed logins, reset requests, sign-ups) for rate limiting.
CREATE TABLE IF NOT EXISTS rate_events (
  bucket TEXT NOT NULL,
  key    TEXT NOT NULL,
  at     INTEGER NOT NULL
);

-- --------------------------------------------------------- placement fee terms
-- Each published version is permanent: it is the record of what employers agreed to.
-- terms_text is the full wording shown to employers (to be drafted by a lawyer).
CREATE TABLE IF NOT EXISTS fee_terms (
  version        INTEGER PRIMARY KEY,
  fee_percent    REAL NOT NULL CHECK (fee_percent > 0 AND fee_percent <= 100),
  min_fee_aud    REAL CHECK (min_fee_aud IS NULL OR min_fee_aud >= 0),
  fee_basis      TEXT NOT NULL,                    -- what salary the % applies to
  window_months  INTEGER NOT NULL CHECK (window_months > 0),
  guarantee_days INTEGER NOT NULL CHECK (guarantee_days >= 0),
  terms_text     TEXT NOT NULL,
  published_at   TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  published_by   TEXT
);

-- SQLite triggers; in PostgreSQL use a BEFORE UPDATE OR DELETE trigger function, or revoke
-- UPDATE/DELETE on this table from the application's database role.
CREATE TRIGGER IF NOT EXISTS fee_terms_no_update BEFORE UPDATE ON fee_terms
BEGIN SELECT RAISE(ABORT, 'published fee terms cannot be changed'); END;
CREATE TRIGGER IF NOT EXISTS fee_terms_no_delete BEFORE DELETE ON fee_terms
BEGIN SELECT RAISE(ABORT, 'published fee terms cannot be deleted'); END;

-- Which employer accepted which version, and who clicked accept. No ON DELETE CASCADE:
-- these are contract records and must not vanish with an account.
CREATE TABLE IF NOT EXISTS terms_acceptances (
  employer_id   TEXT NOT NULL REFERENCES employers (id),
  terms_version INTEGER NOT NULL REFERENCES fee_terms (version),
  accepted_by   TEXT NOT NULL,                     -- user id
  accepted_at   TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (employer_id, terms_version)
);

-- An introduction is the moment an employer unlocked a candidate's details: the event that
-- starts the placement fee window. No foreign keys, so the record survives if the candidate
-- deletes their account (ids only, no personal details). One per candidate and employer.
CREATE TABLE IF NOT EXISTS introductions (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  candidate_id  TEXT NOT NULL,
  employer_id   TEXT NOT NULL,
  job_id        TEXT,
  terms_version INTEGER NOT NULL,
  unlocked_by   TEXT NOT NULL,                     -- user id
  unlocked_at   TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (candidate_id, employer_id)
);

-- ------------------------------------------------------------------- billing
-- Placement fees are invoiced and paid by bank transfer. Money is stored in whole cents.
-- A placement is a hire the employer (or an admin) reported for a candidate they unlocked.
-- No ON DELETE CASCADE: these are business and tax records and must outlive accounts.
CREATE TABLE IF NOT EXISTS placements (
  id                TEXT PRIMARY KEY,
  introduction_id   INTEGER NOT NULL REFERENCES introductions (id),
  candidate_id      TEXT NOT NULL,                 -- no FK: survives account deletion
  candidate_name    TEXT NOT NULL,                 -- as at the hire, for the invoice
  employer_id       TEXT NOT NULL REFERENCES employers (id),
  job_id            TEXT,
  job_title         TEXT,
  start_date        TEXT NOT NULL,
  base_salary_cents INTEGER NOT NULL CHECK (base_salary_cents > 0),
  terms_version     INTEGER NOT NULL REFERENCES fee_terms (version),
  fee_cents         INTEGER NOT NULL CHECK (fee_cents >= 0),  -- 0 when hired outside the fee window
  status            TEXT NOT NULL DEFAULT 'recorded' CHECK (status IN ('recorded', 'cancelled')),
  reported_by       TEXT NOT NULL,                 -- user id
  reported_at       TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  cancelled_reason  TEXT
);
-- one active hire per introduction (a cancelled one can be recorded again)
CREATE UNIQUE INDEX IF NOT EXISTS idx_placements_active ON placements (introduction_id) WHERE status = 'recorded';

-- An invoice is 'scheduled' (not yet issued, no number) until its issue date, then 'issued'
-- with the next number, then 'paid' or 'void'. Once issued, amounts, dates, number and the
-- seller, buyer and bank details can't change (triggers below): fix mistakes by voiding and
-- issuing a new one.
CREATE TABLE IF NOT EXISTS invoices (
  id               TEXT PRIMARY KEY,
  seq              INTEGER UNIQUE,                 -- 1, 2, 3... set when issued
  number           TEXT UNIQUE,                    -- e.g. MM-00001, set when issued
  employer_id      TEXT NOT NULL REFERENCES employers (id),
  placement_id     TEXT REFERENCES placements (id),
  kind             TEXT NOT NULL CHECK (kind IN ('placement', 'services')),
  status           TEXT NOT NULL DEFAULT 'scheduled' CHECK (status IN ('scheduled', 'issued', 'paid', 'void')),
  issue_date       TEXT NOT NULL,
  due_date         TEXT NOT NULL,
  subtotal_cents   INTEGER NOT NULL CHECK (subtotal_cents >= 0),
  gst_cents        INTEGER NOT NULL DEFAULT 0 CHECK (gst_cents >= 0),
  total_cents      INTEGER NOT NULL CHECK (total_cents >= 0),
  gst_registered   INTEGER CHECK (gst_registered IN (0, 1)),
  seller_json      TEXT,                           -- snapshots taken when issued
  buyer_json       TEXT,
  payment_json     TEXT,
  created_by       TEXT,
  created_at       TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  issued_at        TEXT,
  paid_on          TEXT,
  paid_recorded_by TEXT,
  payment_note     TEXT,
  voided_at        TEXT,
  void_reason      TEXT,
  reminders_sent   INTEGER NOT NULL DEFAULT 0,
  last_reminder_on TEXT,
  CHECK (total_cents = subtotal_cents + gst_cents),
  CHECK (status IN ('scheduled', 'void') OR number IS NOT NULL)
);

CREATE TABLE IF NOT EXISTS invoice_lines (
  invoice_id   TEXT NOT NULL REFERENCES invoices (id),
  line_no      INTEGER NOT NULL,
  description  TEXT NOT NULL,
  amount_cents INTEGER NOT NULL CHECK (amount_cents >= 0),  -- excluding GST
  PRIMARY KEY (invoice_id, line_no)
);

-- SQLite triggers; in PostgreSQL use trigger functions with the same conditions.
CREATE TRIGGER IF NOT EXISTS invoices_locked_once_issued
BEFORE UPDATE OF seq, number, employer_id, placement_id, kind, issue_date, due_date, subtotal_cents,
                 gst_cents, total_cents, gst_registered, seller_json, buyer_json, payment_json ON invoices
WHEN OLD.status <> 'scheduled'
BEGIN SELECT RAISE(ABORT, 'issued invoices cannot be changed: void it and issue a new one'); END;
CREATE TRIGGER IF NOT EXISTS invoices_void_is_final BEFORE UPDATE OF status ON invoices
WHEN OLD.status = 'void' AND NEW.status <> 'void'
BEGIN SELECT RAISE(ABORT, 'void invoices cannot be reopened'); END;
CREATE TRIGGER IF NOT EXISTS invoices_never_deleted BEFORE DELETE ON invoices
WHEN OLD.status <> 'scheduled'
BEGIN SELECT RAISE(ABORT, 'issued invoices cannot be deleted: void them instead'); END;
CREATE TRIGGER IF NOT EXISTS invoice_lines_locked_insert BEFORE INSERT ON invoice_lines
WHEN (SELECT status FROM invoices WHERE id = NEW.invoice_id) <> 'scheduled'
BEGIN SELECT RAISE(ABORT, 'lines of an issued invoice cannot be changed'); END;
CREATE TRIGGER IF NOT EXISTS invoice_lines_locked_update BEFORE UPDATE ON invoice_lines
WHEN (SELECT status FROM invoices WHERE id = OLD.invoice_id) <> 'scheduled'
BEGIN SELECT RAISE(ABORT, 'lines of an issued invoice cannot be changed'); END;
CREATE TRIGGER IF NOT EXISTS invoice_lines_locked_delete BEFORE DELETE ON invoice_lines
WHEN (SELECT status FROM invoices WHERE id = OLD.invoice_id) <> 'scheduled'
BEGIN SELECT RAISE(ABORT, 'lines of an issued invoice cannot be changed'); END;

-- -------------------------------------------------------- licence reminders
-- One row per reminder sent, so nobody gets the same one twice. stage: 90, 60 or 30 days before
-- expiry, or 0 once expired. Keyed on the expiry date, so renewing a licence starts afresh.
CREATE TABLE IF NOT EXISTS licence_reminders (
  candidate_id TEXT NOT NULL REFERENCES candidates (id) ON DELETE CASCADE,
  item_id      TEXT NOT NULL REFERENCES catalog_items (id),
  expiry_date  TEXT NOT NULL,
  stage        INTEGER NOT NULL CHECK (stage IN (90, 60, 30, 0)),
  sent_on      TEXT NOT NULL,
  PRIMARY KEY (candidate_id, item_id, expiry_date, stage)
);

-- --------------------------------------------------------------------- indexes
CREATE INDEX IF NOT EXISTS idx_candidates_location     ON candidates (location);
CREATE INDEX IF NOT EXISTS idx_candidates_active       ON candidates (is_active);
CREATE INDEX IF NOT EXISTS idx_documents_candidate     ON documents (candidate_id);
CREATE INDEX IF NOT EXISTS idx_cand_licences_item      ON candidate_licences (item_id, expiry_date);
CREATE INDEX IF NOT EXISTS idx_cand_quals_item         ON candidate_qualifications (item_id);
CREATE INDEX IF NOT EXISTS idx_cand_skills_item        ON candidate_skills (item_id);
CREATE INDEX IF NOT EXISTS idx_experience_candidate    ON candidate_experience (candidate_id);
CREATE INDEX IF NOT EXISTS idx_jobs_status             ON jobs (status);
CREATE INDEX IF NOT EXISTS idx_jobs_employer           ON jobs (employer_id);
CREATE INDEX IF NOT EXISTS idx_job_requirements_item   ON job_requirements (item_id);
CREATE INDEX IF NOT EXISTS idx_shortlists_employer     ON shortlists (employer_id);
CREATE INDEX IF NOT EXISTS idx_shortlist_entries_cand  ON shortlist_entries (candidate_id);
CREATE INDEX IF NOT EXISTS idx_releases_employer       ON contact_releases (employer_id);
CREATE INDEX IF NOT EXISTS idx_audit_user              ON audit_log (user_id, id);
CREATE INDEX IF NOT EXISTS idx_audit_resource          ON audit_log (resource_type, resource_id);
CREATE INDEX IF NOT EXISTS idx_sessions_user           ON sessions (user_id);
CREATE INDEX IF NOT EXISTS idx_auth_tokens_user        ON auth_tokens (user_id, purpose);
CREATE INDEX IF NOT EXISTS idx_rate_events             ON rate_events (bucket, key, at);
CREATE INDEX IF NOT EXISTS idx_introductions_employer  ON introductions (employer_id, unlocked_at);
CREATE INDEX IF NOT EXISTS idx_placements_employer      ON placements (employer_id, start_date);
CREATE INDEX IF NOT EXISTS idx_invoices_employer        ON invoices (employer_id, issue_date);
CREATE INDEX IF NOT EXISTS idx_invoices_status_due      ON invoices (status, due_date);
CREATE UNIQUE INDEX IF NOT EXISTS idx_candidates_reminder_token ON candidates (reminder_token);
CREATE INDEX IF NOT EXISTS idx_cand_licences_expiry    ON candidate_licences (expiry_date);
CREATE INDEX IF NOT EXISTS idx_licence_reminders_sent  ON licence_reminders (sent_on);
